        m_home = new Home::HomeWebView(&frame, *m_theme, frame, m_status_row->spool_store());
        m_home->Hide();

        // The printer conversation lives beside Home's page, in the column
        // the printers list otherwise holds, and Home's own actions open it.
        m_printer_panel = new PrinterSetup::PrinterPanel(
            m_home, *m_theme, GUI_App::dark_mode(), *m_workspace, *plater, m_status_row->spool_store(),
            PrinterSetup::PrinterPanel::Callbacks{
                // `added` is carried through from a successful Add's own
                // close_panel() call, so this refresh -- not a bare one a
                // moment later -- is the one that hands Home the receipt.
                // See IConversationHost::close_panel.
                [this](const PrinterSetup::PinnedFacts* added) {
                    m_home->show_side_panel(false);
                    refresh_home(added);
                },
                [this](const PrinterSetup::PinnedFacts* added) { refresh_home(added); },
                [this] { mark_agent_config_possibly_changed(); }});
        m_home->attach_side_panel(m_printer_panel, m_theme->metrics().printer_card.column_width);
        m_home->backend().set_conversation_opener(
            [this](const std::string& printer_name, bool connect) { open_printer_conversation(printer_name, connect); });

        main_sizer.Detach(&tabpanel);
        m_center_sizer = new wxBoxSizer(wxHORIZONTAL);
        m_workspace_sizer = new wxBoxSizer(wxVERTICAL);
        m_workspace_sizer->Add(&tabpanel, 1, wxEXPAND);
        m_workspace_sizer->Add(m_home, 1, wxEXPAND);
{
    if (m_printer_panel == nullptr || m_home == nullptr || m_tabpanel == nullptr)
        return;
    // The panel lives on Home, so the printer menu's own entries come here
    // first. Selecting the tab refreshes the gallery on its way in.
    if (m_tabpanel->GetSelection() != MainFrame::tpHome)
        m_frame->select_tab(size_t(MainFrame::tpHome));
    m_printer_panel->open(connect ? PrinterSetup::ConversationMode::Connect : printer_name.empty() ? PrinterSetup::ConversationMode::Add :
                                                 PrinterSetup::ConversationMode::Change,
                          printer_name);
    m_home->show_side_panel(true);
}

void ShellController::on_page_changed()
{
    if (!m_installed || m_home == nullptr || m_tabpanel == nullptr)
        return;
    const bool home = m_tabpanel->GetSelection() == MainFrame::tpHome;
    if (home)
        m_home->refresh();
    // A throwaway setup webview elsewhere (the Add a printer dialog) may have
    // written a working agent config since the docked pane last checked; push
    // it in now, the same "refresh on the way in" pattern as Home's gallery
    // above, rather than reloading the page or polling continuously.
    if (m_agent_config_possibly_changed) {
// Applies the repository's design tokens as CSS custom properties.
// resources/jusprin/ui/design-tokens.json is the implementation source of
// truth; the stylesheet must use var(--...) rather than literal colors,
// radii, or type metrics. styles.test.ts enforces that on the stylesheet.
//
// The universal part lives in WebShared/tokens.ts, shared with the Home page.
// Only the Agent page's own component variables are written here.

import tokens from '@resources/jusprin/ui/design-tokens.json';
import { applySharedStaticTokens, sharedStaticVariableNames } from '@shared/tokens';

export { applyAppearance } from '@shared/tokens';

// Every --font-*, --button-*, and Agent-page variable applyStaticTokens
// writes, so a test can check that the stylesheet only asks for variables
// that exist.
export function staticVariableNames(): string[] {
  return [...sharedStaticVariableNames(), '--thread-row-line-gap', '--printer-dialog-scrim'];
}

// In addition to the shared radii, fonts, and button paddings:
//   --thread-row-line-gap  the space between a thread row's title and its
//                          metadata line, an internal size of the row
//   --printer-dialog-scrim the printer panel's own dialog shade, a
//                          percentage for color-mix() -- the same
//                          component.printerDialog token Home's rename and
//                          remove dialogs use, so every printer-feature
//                          dialog reads the same weight over the page.
export function applyStaticTokens(): void {
  applySharedStaticTokens();
  const { component } = tokens as unknown as {
    component: { threadRow: { lineGap: number }; printerDialog: { scrimAlpha: number } };
  };
  document.documentElement.style.setProperty('--thread-row-line-gap', `${component.threadRow.lineGap}px`);
  document.documentElement.style.setProperty(
    '--printer-dialog-scrim',
    `${Math.round((component.printerDialog.scrimAlpha / 255) * 100)}%`,
  );
}
